const records = [
  {id:1,name:'Maria Santos',born:'May 12, 1945',died:'March 18, 2021',block:'A',lot:'024',grave:'01',initials:'MS'},
  {id:2,name:'Jose Dela Cruz',born:'June 8, 1938',died:'November 2, 2019',block:'B',lot:'012',grave:'02',initials:'JC'},
  {id:3,name:'Elena Reyes',born:'August 21, 1952',died:'January 9, 2023',block:'A',lot:'031',grave:'01',initials:'ER'},
  {id:4,name:'Antonio Garcia',born:'April 3, 1940',died:'July 14, 2020',block:'C',lot:'008',grave:'03',initials:'AG'},
  {id:5,name:'Rosa Mendoza',born:'December 16, 1948',died:'February 6, 2022',block:'D',lot:'016',grave:'01',initials:'RM'},
];
const state={role:'Visitor',page:'home',selected:1,query:'',filter:'All blocks',saved:new Set([1]),route:false,pass:null,history:[],name:'Jamie Dela Cruz'};
const content=document.querySelector('#content');
const dialog=document.querySelector('#details');
const escapeHtml=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs={Visitor:[['home','⌂','Overview'],['search','⌕','Find a grave'],['map','◇','Cemetery map'],['pass','▦','Visit pass'],['history','◷','Visit history'],['profile','○','My profile']], 'Lot owner':[['home','⌂','My lots'],['search','⌕','Find a grave'],['map','◇','Cemetery map'],['profile','○','My profile']], 'Gate officer':[['home','▦','Check in visitor'],['history','◷','Visitor log'],['map','◇','Cemetery map']],Admin:[['home','⌂','Dashboard'],['records','▤','Burial records'],['lots','◇','Lot management'],['map','⌖','Map overview'],['history','◷','Visitor logs']]};
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3500)}
function go(page){if(location.hash===`#${page}`)render();else location.hash=page}
function heading(title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">EVERGREEN MEMORIAL PARK</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function row(r){return `<button class="record" data-detail="${r.id}"><span class="initial">${r.initials}</span><span><strong>${r.name}</strong><small>Block ${r.block} · Lot ${r.lot} · Grave ${r.grave}</small></span><span class="arrow-inline">↗</span></button>`}
function art(){return `<svg class="hero-art" viewBox="0 0 260 260" fill="none" aria-hidden="true"><circle cx="145" cy="135" r="100" stroke="currentColor"/><circle cx="145" cy="135" r="82" stroke="currentColor"/><path d="M142 260V80M142 190C60 180 75 100 75 100c60 10 67 50 67 90ZM143 150c65-5 64-70 64-70-60 10-64 45-64 70ZM143 109c-42-21-22-79-22-79 41 28 39 50 22 79Z" stroke="currentColor" stroke-width="2"/></svg>`}
function mapSvg(mini=false){return `<div class="map-frame ${mini?'mini-map':''}"><svg viewBox="0 0 700 470" role="img" aria-label="Illustrative cemetery map. Select a block using the buttons below."><defs><pattern id="grass" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="currentColor" opacity=".06"/></pattern></defs><rect width="700" height="470" fill="url(#grass)"/><path class="map-road" d="M350 470V45M50 235H650M90 65H610V405H90Z"/><path d="M350 470V45M50 235H650" stroke="var(--muted)" opacity=".25" stroke-dasharray="4 8" fill="none"/>${['A','B','C','D'].map((b,i)=>{const x=i%2?397:130,y=i<2?94:274;return `<g data-block="${b}"><rect class="map-lot ${records.find(r=>r.id===state.selected).block===b?'selected':''}" x="${x}" y="${y}" width="174" height="111" rx="9"/>${Array.from({length:12},(_,j)=>`<rect x="${x+16+(j%6)*25}" y="${y+17+Math.floor(j/6)*25}" width="16" height="16" rx="3" fill="var(--muted)" opacity=".23"/>`).join('')}<text x="${x+87}" y="${y+92}" text-anchor="middle" class="map-text">BLOCK ${b}</text></g>`}).join('')}<circle cx="350" cy="235" r="27" fill="var(--map)" stroke="var(--road)" stroke-width="8"/><circle cx="350" cy="235" r="11" fill="#839b65"/>${[40,660].map(x=>[100,160,300,360].map(y=>`<circle cx="${x}" cy="${y}" r="17" fill="#5e7950" opacity=".35"/><circle cx="${x-3}" cy="${y-4}" r="11" fill="#839b65" opacity=".25"/>`).join('')).join('')}${state.route?`<path class="route" d="M350 440V${['A','B'].includes(records.find(r=>r.id===state.selected).block)?145:320}H${['A','C'].includes(records.find(r=>r.id===state.selected).block)?215:482}"/>`:''}<circle class="pin" cx="${['A','C'].includes(records.find(r=>r.id===state.selected).block)?215:482}" cy="${['A','B'].includes(records.find(r=>r.id===state.selected).block)?145:320}" r="9"/><text x="370" y="449" class="map-text">MAIN ENTRANCE</text><text x="639" y="38" class="map-text">↑ N</text></svg><span class="map-label">${state.route?'Walking route preview':'Illustrative layout · Not to scale'}</span></div>`}
function home(){return `${heading(`A little closer to those you love.`,`Welcome back, ${escapeHtml(state.name.split(' ')[0])}. Let us help you find your way.`)}<section class="hero">${art()}<div class="eyebrow">A MEMORY. A PLACE. A CONNECTION.</div><h1>Remembering starts<br>with finding.</h1><p>Locate a loved one’s resting place and plan a peaceful visit, all in one place.</p><form class="searchbar" id="home-search"><input name="query" aria-label="Search for a loved one" placeholder="Search a name or lot number…"><button class="primary">Find a grave ↗</button></form></section><div class="grid">${[['map','◇','Explore the grounds','Find blocks, lots, and resting places.'],['pass','▦','Prepare your visit','Create your visitor pass before you arrive.'],['history','◷','Your past visits','A quiet record of moments remembered.']].map(([page,icon,title,copy])=>`<button class="action-card" data-go="${page}"><span class="symbol">${icon}</span><span class="arrow">↗</span><h3>${title}</h3><p>${copy}</p></button>`).join('')}</div><div class="columns"><section class="panel"><div class="panel-head"><h2>Remembered & saved</h2><button class="text" data-go="search">Find someone ↗</button></div>${records.filter(r=>state.saved.has(r.id)).map(row).join('')||'<p class="empty">Save a memorial from its details to keep it here.</p>'}</section><section class="panel"><div class="panel-head"><h2>A place of peace</h2><button class="text" data-go="map">Open map ↗</button></div>${mapSvg(true)}</section></div>`}
function search(){return `${heading('Find a loved one','Search burial records by name, block, or lot number.')}<form class="searchbar" id="search-form"><input id="search-input" aria-label="Search burial records" value="${escapeHtml(state.query)}" placeholder="Try Maria Santos or 024"><button class="primary">Search</button></form><div class="filters">${['All blocks','A','B','C','D'].map(b=>`<button data-filter="${b}" class="${state.filter===b?'active':''}" aria-pressed="${state.filter===b}">${b.length===1?'Block '+b:b}</button>`).join('')}</div><div class="panel results" id="results">${results()}</div>`}
function results(){const found=records.filter(r=>(state.filter==='All blocks'||r.block===state.filter)&&`${r.name} ${r.lot} block ${r.block}`.toLowerCase().includes(state.query.toLowerCase().trim()));return `<div class="panel-head"><h2>${found.length} memorial${found.length===1?'':'s'} found</h2><span class="note">Sample burial records</span></div>${found.map(row).join('')||'<div class="empty"><h3>No matching memorials</h3><p>Try another name or lot number, or select all blocks.</p><button data-action="reset-search">Clear search</button></div>'}`}
function mapPage(){const r=records.find(r=>r.id===state.selected);return `${heading('Find your way, gently.','Explore the grounds and preview a route to a loved one.')}<div class="map-layout"><section class="panel"><div class="panel-head"><h2>Cemetery map</h2><span class="badge">4 blocks</span></div>${mapSvg()}<div class="filters" style="padding:0 20px 20px">${['A','B','C','D'].map(b=>`<button data-block="${b}" class="${r.block===b?'active':''}" aria-pressed="${r.block===b}">Block ${b}</button>`).join('')}</div></section><section class="panel map-info"><div class="eyebrow">SELECTED MEMORIAL</div><h2 class="dialog-title">${r.name}</h2><p>${r.born.split(', ')[1]} — ${r.died.split(', ')[1]}<br>Forever remembered.</p><dl><div><dt>Block</dt><dd>${r.block}</dd></div><div><dt>Lot</dt><dd>${r.lot}</dd></div><div><dt>Grave</dt><dd>${r.grave}</dd></div><div><dt>Starting point</dt><dd>Main entrance</dd></div></dl><div class="stack"><button class="primary" data-action="route">${state.route?'Hide route':'Preview walking route'} ↗</button><button data-detail="${r.id}">View memorial</button><button data-action="create-pass">Create visit pass</button></div><p class="note" style="margin-top:20px">Route is a visual demonstration, not GPS guidance. Confirm directions at the cemetery office.</p></section></div>`}
function passPage(){const r=records.find(r=>r.id===(state.pass?.record||state.selected));return `${heading('A thoughtful visit starts here.','Prepare a demo pass to explore the arrival and check-in flow.')}<section class="panel pass"><span class="badge">${state.pass?.used?'Visit checked in':state.pass?'Ready for demo check-in':'VISITOR PASS'}</span><h2>${state.pass?'Your visit, prepared.':'You’re always welcome.'}</h2><p>Destination: ${r.name}<br>Block ${r.block} · Lot ${r.lot} · Grave ${r.grave}</p><div class="qr-placeholder"><span>▦</span><small>DEMO PASS · NOT SCANNABLE</small></div>${state.pass?`<div class="pass-code">${state.pass.code}</div><p class="note">Valid only inside this prototype session.</p><button class="primary" data-action="gate-preview">Try gate officer check-in ↗</button>`:'<button class="primary" data-action="create-pass">Generate demo pass</button>'}<p class="note" style="margin-top:20px">In the app, a secure QR pass is presented at the gate. This prototype simulates that interaction.</p></section>`}
function history(){return `${heading(state.role==='Visitor'?'Moments remembered.':'Visitor log','Check-ins completed in this prototype session appear here.')}<section class="panel"><div class="panel-head"><h2>${state.history.length} completed visits</h2><span class="badge">Demo session</span></div>${state.history.length?state.history.map(v=>`<div class="record"><span class="initial">✓</span><span><strong>${escapeHtml(v.visitor)} → ${v.name}</strong><small>${v.time} · ${v.code}</small></span><span class="badge arrow-inline">Checked in</span></div>`).join(''):`<div class="empty"><h2>Your story of visits begins here.</h2><p>Generate a pass, then check it in from the gate officer preview.</p><button class="primary" data-action="visitor-pass">Create a visit pass</button></div>`}</section>`}
function gate(){return `${heading('A warm welcome at the gate.','Simulate visitor arrival using a pass created in this prototype.')}<section class="panel settings"><div class="eyebrow">GATE OFFICER</div><h2>Check in a visitor</h2><p>Enter the demo pass code to validate it and record a visit.</p><form id="checkin"><label for="code">Visitor pass code</label><input id="code" name="code" placeholder="EVG-0000" required value="${state.pass?.code||''}"><button class="primary">Validate & check in</button></form><p class="note" style="margin-top:22px">Camera scanning and real visitor credentials are not connected.</p><button class="text" data-action="visitor-pass">Create a sample visitor pass ↗</button></section>`}
function admin(){return `${heading('Care for every detail.','An overview of your memorial park. All figures are sample data.', '<button data-go="records">View burial records ↗</button>')}<div class="grid">${[['Burial records','5','Across four cemetery blocks'],['Occupied lots','5','Sample lots linked to memorials'],['Demo check-ins',state.history.length,'Completed during this session']].map(([title,n,copy])=>`<div class="action-card"><p>${title}</p><strong class="stats">${n}</strong><p>${copy}</p></div>`).join('')}</div><div class="columns"><section class="panel"><div class="panel-head"><h2>Burial records</h2><button class="text" data-go="records">View all ↗</button></div>${records.slice(0,3).map(row).join('')}</section><section class="panel"><div class="panel-head"><h2>Grounds overview</h2><button class="text" data-go="map">Explore ↗</button></div>${mapSvg(true)}</section></div>`}
function recordTable(lots=false){return `${heading(lots?'Every lot, accounted for.':'Preserving their stories.',lots?'Explore the sample block, lot, and grave hierarchy.':'Open a burial record to view its memorial and location.')}<section class="panel table-scroll"><table><thead><tr><th>${lots?'Lot number':'Name'}</th><th>Block</th><th>${lots?'Memorial':'Lot / Grave'}</th><th>Status</th><th>Details</th></tr></thead><tbody>${records.map(r=>`<tr><td>${lots?r.lot:r.name}</td><td>Block ${r.block}</td><td>${lots?r.name:r.lot+' / '+r.grave}</td><td><span class="badge">${lots?'Occupied':'Recorded'}</span></td><td><button data-detail="${r.id}">View ↗</button></td></tr>`).join('')}</tbody></table></section>`}
function owner(){return `${heading('A place held close.','Your sample lot and its linked memorial.')}<section class="panel settings"><span class="badge">LOT OWNER</span><h2 class="dialog-title" style="margin-top:20px">Block A · Lot 024</h2><p>Linked memorial: Maria Santos<br>Grave 01 · Occupied</p><div class="stack"><button class="primary" data-detail="1">View memorial ↗</button><button data-action="owner-map">Locate my lot</button></div><p class="note" style="margin-top:22px">Sample ownership information for this design preview.</p></section>`}
function profile(){return `${heading('Make yourself at home.','Manage your demo profile and display preferences.')}<section class="panel settings"><form id="profile-form"><label for="display-name">Display name</label><input id="display-name" name="name" maxlength="60" required value="${escapeHtml(state.name)}"><label>Email address</label><p>jamie@example.com · Demo account</p><button class="primary">Save profile</button></form><hr style="border:0;border-top:1px solid var(--line);margin:26px 0"><h2>Appearance</h2><p>Choose a comfortable setting for your visit.</p><button data-action="theme">Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} mode</button><p class="note" style="margin-top:20px">Profile changes last for this session. Theme preference is saved when browser storage is available.</p></section>`}
function render(){const requested=location.hash.slice(1)||'home';state.page=navs[state.role].some(n=>n[0]===requested)?requested:'home';document.querySelector('#role').value=state.role;document.querySelector('#navigation').innerHTML=navs[state.role].map(([page,icon,label])=>`<a href="#${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('');document.querySelector('#breadcrumb').textContent=`${state.role} / ${navs[state.role].find(n=>n[0]===state.page)[2]}`;const pages={home:state.role==='Admin'?admin:state.role==='Gate officer'?gate:state.role==='Lot owner'?owner:home,search,map:mapPage,pass:passPage,history,profile,records:()=>recordTable(),lots:()=>recordTable(true)};content.innerHTML=pages[state.page]();document.querySelector('.account > span:last-child').innerHTML=`${escapeHtml(state.name)}<small>Demo account</small>`}
function showDetails(id){state.selected=Number(id);const r=records.find(r=>r.id===state.selected);document.querySelector('#dialog-content').innerHTML=`<div class="dialog-top"><span class="eyebrow" style="margin:0">IN LOVING MEMORY</span><button data-action="close" aria-label="Close memorial details">✕</button></div><h2 class="dialog-title">${r.name}</h2><p>Always loved. Forever remembered.</p><dl class="detail-grid"><div><dt>Date of birth</dt><dd>${r.born}</dd></div><div><dt>Date of passing</dt><dd>${r.died}</dd></div><div><dt>Resting place</dt><dd>Block ${r.block} · Lot ${r.lot}</dd></div><div><dt>Grave number</dt><dd>${r.grave}</dd></div></dl><div class="stack"><button class="primary" data-action="detail-map">Find on map ↗</button><button data-action="save">${state.saved.has(r.id)?'Remove from saved memorials':'♡ Save memorial'}</button>${state.role==='Visitor'?'<button data-action="create-pass">Create visit pass</button>':''}</div><p class="note" style="margin:20px 0 0">Fictional record for prototype demonstration.</p>`;if(!dialog.open)dialog.showModal()}
function theme(){const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;try{localStorage.setItem('evergreen-prototype-theme',value)}catch{}updateThemeLabel();if(state.page==='profile')render()}
function updateThemeLabel(){document.querySelector('#theme').innerHTML=`${document.documentElement.dataset.theme==='dark'?'☀':'☾'} <span>Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} mode</span>`}
function changeRole(role,page='home'){state.role=role;go(page)}
document.addEventListener('click',event=>{const el=event.target.closest('[data-go],[data-detail],[data-action],[data-filter],[data-block]');if(!el)return;if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.detail){showDetails(el.dataset.detail);return}if(el.dataset.filter){state.filter=el.dataset.filter;render();return}if(el.dataset.block){state.selected=records.find(r=>r.block===el.dataset.block).id;render();return}switch(el.dataset.action){case 'close':dialog.close();break;case 'theme':theme();break;case 'route':state.route=!state.route;render();break;case 'reset-search':state.query='';state.filter='All blocks';render();break;case 'detail-map':dialog.close();state.route=false;go('map');break;case 'owner-map':state.selected=1;go('map');break;case 'save':state.saved.has(state.selected)?state.saved.delete(state.selected):state.saved.add(state.selected);showDetails(state.selected);render();break;case 'create-pass':state.pass={record:state.selected,code:'EVG-'+String(Math.floor(1000+Math.random()*9000)),used:false};dialog.close();changeRole('Visitor','pass');notify('Demo visit pass created');break;case 'gate-preview':changeRole('Gate officer');break;case 'visitor-pass':changeRole('Visitor','pass');break}});
document.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);switch(event.target.id){case 'home-search':state.query=data.get('query');state.filter='All blocks';go('search');break;case 'search-form':state.query=document.querySelector('#search-input').value;render();break;case 'profile-form':{const name=data.get('name').trim();if(!name){notify('Please enter a display name.');return}state.name=name;render();notify('Demo profile updated');break}case 'checkin':{const code=data.get('code').trim().toUpperCase();if(!state.pass||code!==state.pass.code){notify('Pass not found. Create a demo visitor pass first.');return}if(state.pass.used){notify('This pass has already been checked in.');return}state.pass.used=true;const r=records.find(r=>r.id===state.pass.record);state.history.unshift({name:r.name,visitor:state.name,code,time:new Date().toLocaleString()});notify('Visitor checked in successfully');go('history');break}}});
document.addEventListener('input',event=>{if(event.target.id==='search-input'){state.query=event.target.value;document.querySelector('#results').innerHTML=results()}});
document.querySelector('#role').addEventListener('change',event=>changeRole(event.target.value));
document.querySelector('#theme').addEventListener('click',theme);
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{render();content.focus();window.scrollTo(0,0)});
try{const saved=localStorage.getItem('evergreen-prototype-theme');if(['light','dark'].includes(saved))document.documentElement.dataset.theme=saved}catch{}
updateThemeLabel();render();
